<script>document.addEventListener('DOMContentLoaded',()=>{const items=[@foreach($products as $p){type:'product',id:'{{ $p->id }}',label:@json($p->nombre.' · '.$p->codigo_interno),search:@json($p->nombre.' '.$p->codigo_interno.' '.$p->numero_parte.' '.$p->marca.' '.$p->modelo)},@endforeach @foreach($assets as $a){type:'asset',id:'{{ $a->id }}',label:@json($a->activo_fijo.' · '.$a->marca.' '.$a->modelo.($a->numero_serie ? ' · Serie '.$a->numero_serie : '')),search:@json($a->activo_fijo.' '.$a->numero_serie.' '.$a->marca.' '.$a->modelo)},@endforeach],cart=[],search=document.getElementById('groupSearch'),results=document.getElementById('groupResults'),q=document.getElementById('itemQty'),b=document.getElementById('addItem'),body=document.getElementById('cart'),json=document.getElementById('itemsJson'),help=document.getElementById('groupSearchHelp');let chosen=null;const norm=s=>(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();function draw(){json.value=JSON.stringify(cart);body.innerHTML=cart.length?cart.map((x,i)=>`<tr><td>${x.label}</td><td>${x.quantity}</td><td class="text-end"><button type="button" class="btn btn-sm btn-outline-danger" data-i="${i}">Quitar</button></td></tr>`).join(''):'<tr><td colspan="3" class="text-body-secondary text-center">Aún no agregas elementos.</td></tr>'}function find(){const term=norm(search.value.trim()),matches=items.filter(x=>term&&norm(x.search).includes(term)).slice(0,20);chosen=null;b.disabled=true;b.textContent='Selecciona un resultado';results.innerHTML=matches.map((x,i)=>`<button type="button" class="asset-picker-option" data-i="${items.indexOf(x)}"><strong>${x.type==='asset'?'Activo fijo':'Producto'} · ${x.label}</strong><span>${x.type==='asset'?'Se trasladará desde la ubicación de origen':'Cantidad según el stock de la bodega'}</span></button>`).join('');help.textContent=term?`${matches.length} resultado(s). Selecciona uno.`:'Escribe para buscar productos y activos.'}search.addEventListener('input',find);results.addEventListener('click',e=>{const option=e.target.closest('[data-i]');if(!option)return;chosen=items[option.dataset.i];search.value=chosen.label;results.innerHTML='';b.disabled=false;b.textContent='Agregar al carrito';help.textContent='Elemento seleccionado.'});b.addEventListener('click',()=>{if(!chosen||cart.some(x=>x.type===chosen.type&&x.id===chosen.id))return;cart.push({...chosen,quantity:chosen.type==='asset'?1:Math.max(1,Number(q.value)||1)});search.value='';chosen=null;b.disabled=true;b.textContent='Selecciona un resultado';draw();find()});body.addEventListener('click',e=>{const i=e.target.dataset.i;if(i!==undefined){cart.splice(i,1);draw()}});draw();find()})</script>
